def _num_equal(rx, ry) -> bool:
    """Value equality for two sympy Numbers.

    NEVER use bare ``==`` here: in sympy 1.14 ``Float.__eq__`` is *structural*
    (``Basic.__eq__``), so ``Float(1.0) == Integer(1)`` and even
    ``Float(0.5) == Rational(1, 2)`` are both False.  ``(rx - ry).is_zero``
    is the value-level test.
    """
    try:
        if rx is ry or rx == ry:
            return True
    except Exception:
        pass
    try:
        return (rx - ry).is_zero is True
    except Exception:
        return False

